/**
 * 内置提示音（由 scripts/gen-tones.mjs 生成 —— 勿手改）。
 * data URL base64 内嵌，client 播放通道直接 new Audio() 使用，
 * 不依赖静态资源服务（FR-6.2：提示音不占用 TTS 合成通道）。
 *
 * 两档音色（T-8）：`soft` 柔和（默认）/ `crisp` 清脆，按配置
 * `feedback.toneStyle` 选择；resolveToneUrl(style, tone) 取对应 data URL。
 */
export type ToneStyle = "soft" | "crisp"

export const TONE_URLS_BY_STYLE = {
  "soft": {
    "ding": "data:audio/wav;base64,",
    "ding-ding": "data:audio/wav;base64,",
    "dong": "data:audio/wav;base64,",
  },
  "crisp": {
    "ding": "data:audio/wav;base64,",
    "ding-ding": "data:audio/wav;base64,",
    "dong": "data:audio/wav;base64,",
  },
} as const

export type ToneAssetKey = keyof typeof TONE_URLS_BY_STYLE["soft"]

/** 按档位取提示音 data URL（style 未知时回退 soft）。 */
export function resolveToneUrl(style: ToneStyle | undefined, tone: ToneAssetKey): string | undefined {
  const table = TONE_URLS_BY_STYLE[style === "crisp" ? "crisp" : "soft"]
  return table[tone]
}
